#if RECOVERY_QA
// Test-only fresh reconstruction QA; no replacement for missing historical native receipts.
#nullable enable
using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Threading.Tasks;
using Godot;using DeckRogue.Engine;using DeckRogue.Engine.Generated;using DeckRogue.Game;using DeckRogue.GodotPort.Core;using DeckRogue.GodotPort.Presentation;using DeckRogue.GodotPort.UI;using Newtonsoft.Json;
namespace DeckRogue.GodotPort.RecoveryQA;
public static class RecoveryMotionQa {
 static Node main=null!;static BattleStage stage=null!;static GameUI ui=null!;static GameSession session=null!;static string output="";static int checks,shot;static readonly List<object> rows=new();static readonly List<string> diagnostics=new();static readonly List<(GameEvent E,float At,long Revision,int? Amount)> contacts=new();static string expectedHash="";
 public static void Start(Node root){if(OS.GetCmdlineUserArgs().Contains("--recovery-motion-qa"))Callable.From((Action)(async()=>await Run(root))).CallDeferred();}
 static IEnumerable<Node> Desc(Node n){foreach(Node c in n.GetChildren()){yield return c;foreach(var d in Desc(c))yield return d;}}
 static BattleActor Hero()=>Desc(stage).OfType<BattleActor>().Single(a=>a.DefinitionId.StartsWith("leader_"));
 static void Check(bool ok,string name){checks++;rows.Add(new{kind="assertion",name,pass=ok});Progress(name);if(!ok)throw new Exception(name);}
 static void Progress(string name){System.IO.File.WriteAllText(Path.Combine(output,"progress.json"),JsonConvert.SerializeObject(new{name,checks,shot}));}
 static string Hash(RunState r)=>Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(JsonUnions.Serialize(r)))).ToLowerInvariant();
 static async Task Frames(int n){for(int i=0;i<n;i++)await main.ToSignal(main.GetTree(),SceneTree.SignalName.ProcessFrame);}
 static RunState Fixture(string[] ids,int[]? hp=null){
  var seed=DeckRogue.Engine.Run.CreateDebugCheckpointRun(52001,"set-confirm","leader_green",new ReplayOriginCheckpoint{Act=1,DeckId="starter",Difficulty=3});
  var run=DeckRogue.Engine.Run.DebugLaunchCombat(seed,seed.Map.SelectMany(r=>r).First(n=>n.Type==MapNodeTypes.Battle&&n.EncounterId!=null).EncounterId!);var state=run.Combat!;
  var template=state.Enemies[0];var enemies=(hp??new[]{1000,1000}).Select(n=>template with{Hp=n,MaxHp=Math.Max(n,1000),Block=0,EnemyId="enemy_probe",Node="poke",IntentMoveId="poke",IntentNode="poke",LastMoves=Array.Empty<string>(),UsedOnce=Array.Empty<string>(),Burn=0,Intent=new EnemyIntent{Kind="attack",Actual=4,Base=4},Strength=0,Exposed=0}).ToArray();
  state=state with{Player=state.Player with{Hand=ids.Select((id,i)=>new CardInstance{Uid="qa-"+i,Def=session.Catalog.Cards.Single(c=>c.Id==id)}).ToArray(),Energy=10,EnergyMax=10,EnergyMaxAtTurnStart=10,Hp=80,MaxHp=80,Block=0,IceBlock=0,Permanents=Array.Empty<CardInstance>(),SetCards=Array.Empty<CardInstance>()},Enemies=enemies};return run with{Combat=state};
 }
 static async Task Load(RunState run,string label){RenderingServer.RenderLoopEnabled=true;main.GetTree().Paused=false;contacts.Clear();var json=Report.SerializeRunSaveFile(new RunSaveFile{Run=run,Fingerprint=session.Catalog.Fingerprint});System.IO.File.WriteAllText(Path.Combine(output,label+".json"),json);Check(session.Load(json).Success,"load-"+label);stage.PlaybackPaused=true;ui.PresentationCompleted();stage.SetInterfaceRoute("combat");await Frames(3);Desc(stage).OfType<StageWorld>().Single().SetProcess(false);main.GetTree().Paused=true;RenderingServer.RenderLoopEnabled=false;expectedHash=Hash(run);Check(!stage.InputLocked&&!stage.IsPresenting,"reset-gates-clear");}
 static void Dispatch(RunCommand c){var next=DeckRogue.Engine.Run.ApplyRunCommand(session.CurrentRun!,c);Check(session.Dispatch(c).Success,"actual-command-accepted");expectedHash=Hash(next);Check(Hash(session.CurrentRun!)==expectedHash,"exact-original-rule-outcome");}
 static RunCommand Play(int i,int target=0)=>new RunCommand_Combat{Command=new Command_PlayCard{CardUid="qa-"+i,TargetIndex=target}};
 static void Pump(float seconds,float dt=.001f){int n=(int)Math.Ceiling(seconds/dt);for(int i=0;i<n;i++)stage.AdvancePresentation(Math.Min(dt,seconds-i*dt));}
 static void Until(Func<bool> done,int max=20000,float dt=.001f){for(int i=0;i<max&&!done();i++)stage.AdvancePresentation(dt);Check(done(),"bounded-condition-reached");}
 static void Drain(){Until(()=>!stage.IsPresenting,20000,.001f);Check(!stage.InputLocked&&!session.PresentationBusy,"drain-releases-input");Check(stage.ActiveMotionCount==0&&stage.PendingCommandCount==0,"drain-motion-queue-empty");Check(Hash(session.CurrentRun!)==expectedHash,"visuals-preserve-rules-rng");}
 static async Task Capture(string name){if(DisplayServer.GetName()=="headless")return;await Frames(3);RenderingServer.ForceDraw(true,0);RenderingServer.ForceSync();using var image=main.GetViewport().GetTexture().GetImage();Check(image.GetWidth()==1170&&image.GetHeight()==540,"native-size");string file=$"{++shot:000}_{name}.png";Check(image.SavePng(Path.Combine(output,file))==Error.Ok,"save-"+name);rows.Add(new{kind="capture",file,sha256=Convert.ToHexString(SHA256.HashData(System.IO.File.ReadAllBytes(Path.Combine(output,file)))).ToLowerInvariant(),clock=stage.PresentationTime,stage.InputLocked,stage.ActiveEffectCount,stage.ActiveMotionCount,stage.ActivePhaseBanner,stage.ActivePhaseBannerAlpha,phaseBannerBounds=stage.PhaseBannerBounds.ToString(),actors=Desc(stage).OfType<BattleActor>().Select(a=>new{a.DefinitionId,pose=a.PoseName,frame=a.PoseFrame,offset=a.Motion.Offset.ToString(),a.DissolveAmount,a.ExecutionScaleActive}).ToArray()});}
 static async Task Run(Node root){main=root;bool success=false;try{
  var args=OS.GetCmdlineUserArgs();int oi=Array.IndexOf(args,"--recovery-qa-out");output=oi>=0?args[oi+1]:ProjectSettings.GlobalizePath("user://motion-recovery-qa");Directory.CreateDirectory(output);if(System.IO.File.Exists(Path.Combine(output,"results.json")))throw new Exception("Use fresh output directory");await main.ToSignal(main.GetTree().CreateTimer(2),SceneTreeTimer.SignalName.Timeout);var window=main.GetTree().Root;window.ContentScaleSize=new(1600,900);window.ContentScaleMode=Window.ContentScaleModeEnum.CanvasItems;window.ContentScaleAspect=Window.ContentScaleAspectEnum.Expand;window.Size=new(1170,540);await Frames(3);
  stage=main.GetNode<BattleStage>("BattleStage");ui=main.GetNode<GameUI>("Interface/GameUI");session=new GameSession{Name="MotionQaSession",SaveDirectory=Path.Combine(output,"isolated-session"),AutoSave=false};main.AddChild(session);session.Diagnostic+=diagnostics.Add;stage.Bind(session);ui.Bind(session);stage.PlaybackPaused=true;
  stage.EventPresented+=e=>contacts.Add((e,stage.PresentationTime,stage.GetEventChange(e)?.Revision??-1,null));stage.NumericContactPresented+=e=>{int? amount=stage.GetPresentedIncomingAmount(e);if(e is GameEvent_DamageDealt{Source:"enemy"})Check(amount.HasValue,"incoming-callback-owned");};
  if(args.Contains("--recovery-banner-only")) { await Load(Fixture(Array.Empty<string>()),"banner-only"); Dispatch(new RunCommand_Combat{Command=new Command_EndTurn()}); Until(()=>stage.ActivePhaseBanner=="敵の番"); Pump(.16f); Check(stage.ActivePhaseBannerAlpha>.99f,"source-banner-visible-after-fade-in"); Check(stage.PhaseBannerBounds.Size.X>0&&stage.PhaseBannerBounds.Size.Y>0,"source-banner-positive-bounds"); await Capture("enemy-banner-visible"); Drain(); Write(true,null);success=true;GD.Print("RECOVERY_BANNER_QA_PASS checks="+checks);return; }
  await Load(Fixture(new[]{"green_strike","green_strike","green_strike"}),"rapid3");var start=stage.PresentationTime;int initial=stage.DamageContactCount;
  Dispatch(Play(0));Dispatch(Play(1));Dispatch(Play(2));Check(!stage.InputLocked&&stage.PendingCommandCount==3,"three-cards-accepted-before-contact");Check(contacts.Count==0,"no-synchronous-contact");
  Pump(.055f);Check(Hero().Motion.HasMotion&&Hero().Motion.Offset.Length()>0,"source-anticipation-motion");await Capture("source-anticipation");Until(()=>stage.DamageContactCount>initial);float first=stage.PresentationTime;Check(Math.Abs(first-stage.LastActorLaunchAt-.13f)<.002f,"source130ms-contact");Check(Hero().Motion.IsPaused(first),"source-local-hold");await Capture("source-contact-hold");int launched=stage.ActorActionLaunchCount;Pump(.06f);Check(stage.ActorActionLaunchCount==launched,"65ms-hold-retains-owner");Until(()=>stage.ActorActionLaunchCount>launched);Check(stage.PresentationTime-first>=.064f,"successor-after-local-pause");Check(stage.ResidualEffectCount>0,"successor-before-prior-fx-tail");Drain();Check(stage.DamageContactCount-initial==3,"three-contacts-once");Check(contacts.Where(x=>x.E is GameEvent_DamageDealt).Select(x=>x.Revision).Distinct().Count()==3,"per-command-receipt-ownership");
  await Load(Fixture(new[]{"green_strike","green_guard"}),"mixed");initial=stage.DamageContactCount;Dispatch(Play(0));Until(()=>stage.DamageContactCount>initial);Check(!stage.InputLocked,"ordinary-local-pause-does-not-lock-input");Dispatch(Play(1));Drain();Check(session.CurrentRun!.Combat!.Player.Block>0,"guard-rule-applied");
  await Load(Fixture(new[]{"green_earth_roar"},new[]{6,1000,12}) with{Combat=Fixture(new[]{"green_earth_roar"},new[]{6,1000,12}).Combat! with{Player=Fixture(new[]{"green_earth_roar"}).Combat!.Player with{Energy=5,EnergyMax=5,EnergyMaxAtTurnStart=5}}},"earth-mixed-death");initial=stage.DamageContactCount;Dispatch(Play(0));Until(()=>stage.ActorActionLaunchCount>launched);Drain();Check(stage.DamageContactCount-initial>=3,"aoe-actual-contacts");var ht=contacts.Where(x=>x.E is GameEvent_DamageDealt{Source:"player"}).Select(x=>x.At).ToArray();rows.Add(new{kind="aoe-contact-times",times=ht});Check(ht.Select(t=>MathF.Round(t-ht[0],2)).Distinct().Count()<=2,"aoe-two-source-volleys");
  await Load(Fixture(new[]{"green_strike"},new[]{6}),"terminal");Dispatch(Play(0));Check(stage.InputLocked&&session.CurrentRun!.Phase!=RunPhases.Combat,"terminal-immediate-input-fence");Check(!session.Dispatch(Play(0)).Success,"terminal-rejects-future-input");Until(()=>contacts.Any(x=>x.E is GameEvent_EnemyDied));Pump(.2f);Check(stage.InputLocked&&stage.IsPresenting,"terminal-waits-death-motion");await Capture("terminal-death");Drain();
  await Load(Fixture(new[]{"green_strike","green_strike"}),"endturn-tail");initial=stage.DamageContactCount;Dispatch(Play(0));Until(()=>stage.DamageContactCount>initial);Check(stage.ActiveEffectCount>0,"endturn-during-live-tail");Dispatch(new RunCommand_Combat{Command=new Command_EndTurn()});Check(stage.InputLocked&&session.PresentationBusy,"enemy-phase-strong-fence");Check(!session.Dispatch(Play(1)).Success,"enemy-phase-rejects-card");Until(()=>stage.ActivePhaseBanner=="敵の番");await Capture("enemy-banner");Drain();Check(stage.EnemyExecutionCount>=2,"source-execution-leases");Check(contacts.All(x=>stage.GetPresentedIncomingAmount(x.E)==null),"incoming-provider-cleared-outside-callback");
  var trio=Fixture(Array.Empty<string>(),new[]{1000,1000,1000});trio=trio with{Combat=trio.Combat! with{Enemies=trio.Combat!.Enemies.Select((e,i)=>e with{Intent=i==0?new EnemyIntent{Kind="attack",Actual=4,Base=4}:i==1?new EnemyIntent{Kind="hex",Actual=1,Inflict=new StatusInflict{Status="wound",Amount=1}}:new EnemyIntent{Kind="defend",Actual=8}}).ToArray()}};
  await Load(trio,"attack-hex-defend");Dispatch(new RunCommand_Combat{Command=new Command_EndTurn()});float st=stage.PresentationTime;int frames=0;while(stage.IsPresenting&&frames++<1200)stage.AdvancePresentation(1f/60);Check(!stage.IsPresenting,"trio-finite-strong-fence");rows.Add(new{kind="enemy-sequence",frames,seconds=stage.PresentationTime-st,rows=contacts.Select(x=>new{type=x.E.Type,at=x.At-st,x.Revision}).ToArray()});Check(Hash(session.CurrentRun!)==expectedHash,"trio-original-rule-hash");await Capture("next-turn");
  var stall=Fixture(Array.Empty<string>(),new[]{1000});stall=stall with{Combat=stall.Combat! with{Enemies=stall.Combat!.Enemies.Select(e=>e with{Intent=new EnemyIntent{Kind="attack",Actual=1,Base=1,Hits=3}}).ToArray()}};
  await Load(stall,"enemy-stall");var numericTimes=new List<float>();Action<GameEvent> collect=e=>{if(e is GameEvent_DamageDealt {Source:"enemy"})numericTimes.Add(stage.PresentationTime);};stage.NumericContactPresented+=collect;Dispatch(new RunCommand_Combat{Command=new Command_EndTurn()});
  stage.AdvancePresentation(.001f);stage.AdvancePresentation(1.5f);for(int i=0;i<300&&numericTimes.Count<3;i++)stage.AdvancePresentation(1f/60);stage.NumericContactPresented-=collect;
  Check(numericTimes.Count==3,"stalled-three-contributions-observed");Check(numericTimes[1]-numericTimes[0]>=.10f&&numericTimes[2]-numericTimes[1]>=.10f,"stall-does-not-burst-catchup-contacts");Drain();
  await Load(Fixture(new[]{"green_strike"}),"numeric-cancel");int beforeAudio=stage.DamageAudioCount;int presentedHits=0;Action<GameEvent> countDamage=e=>{if(e is GameEvent_DamageDealt)presentedHits++;};Action<GameEvent> cancelNumeric=e=>{if(e is GameEvent_DamageDealt)stage.CancelPresentation(false);};stage.EventPresented+=countDamage;stage.NumericContactPresented+=cancelNumeric;Dispatch(Play(0));Until(()=>!stage.IsPresenting);stage.EventPresented-=countDamage;stage.NumericContactPresented-=cancelNumeric;Check(stage.DamageAudioCount==beforeAudio&&presentedHits==0&&stage.ActiveEffectCount==0&&stage.ActiveMotionCount==0,"numeric-cancel-no-stale-feedback");
  await Load(Fixture(new[]{"green_strike","green_strike","green_strike"}),"cancel");Dispatch(Play(0));Dispatch(Play(1));Pump(.07f);stage.CancelPresentation();Check(!stage.IsPresenting&&!stage.InputLocked&&stage.ActiveMotionCount==0&&stage.PendingCommandCount==0&&stage.ActiveEffectCount==0,"cancel-drains-motion-fx-queue");var count=stage.DamageContactCount;Pump(1);Check(stage.DamageContactCount==count,"canceled-callbacks-never-replay");
  await Load(Fixture(new[]{"green_strike"}),"reentry");Dispatch(Play(0));Pump(.02f);await Load(Fixture(new[]{"green_guard"}),"reset-queued");Pump(1);Check(!stage.IsPresenting&&stage.ActiveMotionCount==0,"reset-cancels-old-owner");Check(diagnostics.Count==0,"no-session-diagnostics");Write(true,null);success=true;GD.Print("RECOVERY_MOTION_QA_PASS checks="+checks);
 }catch(Exception e){try{Write(false,e.ToString());}catch{}GD.PrintErr(e);}finally{RenderingServer.RenderLoopEnabled=true;main.GetTree().Paused=false;main.GetTree().Quit(success?0:1);}}
 static void Write(bool pass,string? error)=>System.IO.File.WriteAllText(Path.Combine(output,"results.json"),JsonConvert.SerializeObject(new{loadedMvid=typeof(RecoveryMotionQa).Assembly.ManifestModule.ModuleVersionId,passed=pass,checks,error,diagnostics,results=rows,provenance="Fresh reconstructed motion/P0 tests; no claim of exact lost final-source identity"},Formatting.Indented));
}

